import React, { useState, useRef, useEffect, useCallback } from 'react';
import { Plus, Upload, Search, X, ZoomIn, ZoomOut, Grid, Trash2, Edit } from 'lucide-react';

// Updated color scheme
const colors = {
    primary: '#ff3d7f',
    secondary: '#121212',
    secondaryLight: '#212121',
    light: '#ffffff',
    midGray: '#868686',
    accent: '#00dbdd',
    successGreen: '#4ADE80',
    warningOrange: '#dc6300',
    errorRed: '#FF3D3D'
};

const ConceptBoard = () => {
    const [conceptArt, setConceptArt] = useState([]);
    const [selectedConcept, setSelectedConcept] = useState(null);
    const [scale, setScale] = useState(1);
    const [boardOffset, setBoardOffset] = useState({ x: 0, y: 0 });
    const [isDraggingBoard, setIsDraggingBoard] = useState(false);
    const [dragStartPos, setDragStartPos] = useState({ x: 0, y: 0 });
    const [categories, setCategories] = useState(['Characters', 'Environments', 'Props', 'Effects', 'UI', 'Uploads']);
    const [selectedCategory, setSelectedCategory] = useState('All');
    const [searchTerm, setSearchTerm] = useState('');
    const [showUploadModal, setShowUploadModal] = useState(false);
    const [newConceptCategory, setNewConceptCategory] = useState('');
    const [newConceptTags, setNewConceptTags] = useState('');
    const [gridView, setGridView] = useState(false); // Default to canvas view
    const boardRef = useRef(null);
    const fileInputRef = useRef(null);
    const nextId = useRef(1); // Simple ID generation
    const boardWidthRef = useRef(null);

    useEffect(() => {
        const storedConcepts = localStorage.getItem('conceptBoard_concepts');
        if (storedConcepts) {
            setConceptArt(JSON.parse(storedConcepts));
            const maxId = JSON.parse(storedConcepts).reduce((max, concept) => Math.max(max, concept.id), 0);
            nextId.current = maxId + 1;
        }
    }, []);

    useEffect(() => {
        localStorage.setItem('conceptBoard_concepts', JSON.stringify(conceptArt));
    }, [conceptArt]);

    const handleBoardMouseDown = useCallback((e) => {
        if (e.button === 0 && boardRef.current && e.target === boardRef.current) { // Left click on the board itself
            setIsDraggingBoard(true);
            setDragStartPos({ x: e.clientX, y: e.clientY });
            boardRef.current.style.cursor = 'grabbing';
        }
    }, []);

    const handleBoardMouseMove = useCallback((e) => {
        if (!isDraggingBoard) return;
        setBoardOffset(prevOffset => ({
            x: prevOffset.x + (e.clientX - dragStartPos.x),
            y: prevOffset.y + (e.clientY - dragStartPos.y)
        }));
        setDragStartPos({ x: e.clientX, y: e.clientY });
    }, [isDraggingBoard, dragStartPos]);

    const handleBoardMouseUp = useCallback(() => {
        if (isDraggingBoard) {
            setIsDraggingBoard(false);
            if (boardRef.current) {
                boardRef.current.style.cursor = 'grab';
            }
        }
    }, []);

    const handleBoardWheel = useCallback((e) => {
        e.preventDefault();
        const zoomSpeed = 0.05;
        const newScale = Math.max(0.1, scale - e.deltaY * zoomSpeed);

        // Calculate zoom center relative to the board
        const rect = boardRef.current.getBoundingClientRect();
        const zoomPointX = e.clientX - rect.left;
        const zoomPointY = e.clientY - rect.top;

        // Calculate the change in scale
        const scaleChange = newScale / scale;

        // Adjust the offset to zoom into the cursor position
        setBoardOffset(prevOffset => ({
            x: zoomPointX - (zoomPointX + prevOffset.x) * scaleChange,
            y: zoomPointY - (zoomPointY + prevOffset.y) * scaleChange,
        }));

        setScale(newScale);
    }, [scale]);

    const handleZoomIn = () => {
        setScale(prev => Math.min(prev + 0.1, 3));
    };

    const handleZoomOut = () => {
        setScale(prev => Math.max(prev - 0.1, 0.1));
    };

    const handleResetZoom = () => {
        setScale(1);
        setBoardOffset({ x: 0, y: 0 });
    };

    const handleSelectConcept = (concept) => {
        setSelectedConcept(concept);
    };

    const handleCloseDetail = () => {
        setSelectedConcept(null);
    };

    const handleUploadClick = () => {
        setShowUploadModal(true);
        setNewConceptCategory('');
        setNewConceptTags('');
    };

    const handleFileSelect = (e) => {
        const files = e.target.files;
        if (files && files.length > 0 && boardWidthRef.current) {
            const boardRect = boardWidthRef.current.getBoundingClientRect();
            const centerX = boardRect.width / 2;
            const centerY = 300; // Approximate center of the visible height

            Array.from(files).forEach(file => {
                const reader = new FileReader();
                reader.onload = (event) => {
                    const newConcept = {
                        id: nextId.current++,
                        name: file.name.split('.')[0],
                        thumbnail: event.target.result,
                        fullImage: event.target.result,
                        category: newConceptCategory || 'Uploads',
                        tags: newConceptTags.split(',').map(tag => tag.trim()).filter(tag => tag !== ''),
                        position: {
                            x: centerX / scale - 100, // Adjust for image width
                            y: centerY / scale - 80 // Adjust for image height
                        },
                        scale: 0.5 + Math.random() * 0.5, // Random initial scale
                        createdAt: new Date().toISOString().split('T')[0],
                        notes: ''
                    };
                    setConceptArt(prev => [...prev, newConcept]);
                };
                reader.readAsDataURL(file);
            });
            setShowUploadModal(false);
        }
    };

    const handleToggleView = () => {
        setGridView(prev => !prev);
    };

    const handleDeleteConcept = (id) => {
        setConceptArt(prev => prev.filter(concept => concept.id !== id));
        if (selectedConcept && selectedConcept.id === id) {
            setSelectedConcept(null);
        }
    };

    const handleConceptDragStart = (e, id) => {
        const concept = conceptArt.find(c => c.id === id);
        e.dataTransfer.setData('conceptId', id);
        e.dataTransfer.setData('offsetX', e.clientX - (boardOffset.x + concept.position.x * scale));
        e.dataTransfer.setData('offsetY', e.clientY - (boardOffset.y + concept.position.y * scale));
    };

    const handleConceptDragOver = (e) => {
        e.preventDefault();
    };

    const handleConceptDrop = (e) => {
        const conceptId = parseInt(e.dataTransfer.getData('conceptId'));
        const offsetX = parseFloat(e.dataTransfer.getData('offsetX'));
        const offsetY = parseFloat(e.dataTransfer.getData('offsetY'));

        const newX = (e.clientX - offsetX - boardOffset.x) / scale;
        const newY = (e.clientY - offsetY - boardOffset.y) / scale;

        setConceptArt(prev => prev.map(concept =>
            concept.id === conceptId ? { ...concept, position: { x: newX, y: newY } } : concept
        ));
    };

    const handleUpdateConcept = (updatedConcept) => {
        setConceptArt(prev =>
            prev.map(c => (c.id === updatedConcept.id ? updatedConcept : c))
        );
        setSelectedConcept(updatedConcept);
    };

    const filteredConcepts = conceptArt.filter(concept => {
        const matchesSearch =
            concept.name.toLowerCase().includes(searchTerm.toLowerCase()) ||
            concept.tags.some(tag => tag.toLowerCase().includes(searchTerm.toLowerCase()));

        const matchesCategory = selectedCategory === 'All' || concept.category === selectedCategory;

        return matchesSearch && matchesCategory;
    });

    return (
        <div className="rounded-lg p-4 h-full fade-in" style={{ backgroundColor: colors.secondary }}>
            <div className="flex justify-between items-center mb-6">
                <div>
                    <h2 className="text-xl font-bold text-white mb-2">Concept Art Board</h2>
                    <p className="text-gray-400">Organize and reference your visual development assets</p>
                </div>

                <div className="flex space-x-2">
                    <button
                        className="px-3 py-2 rounded flex items-center text-white hover-scale transition-all"
                        style={{ backgroundColor: colors.accent }}
                        onClick={handleUploadClick}
                    >
                        <Upload className="h-4 w-4 mr-1" />
                        <span>Upload</span>
                    </button>

                    <button
                        className="p-2 rounded text-white hover-scale transition-all"
                        style={{ backgroundColor: gridView ? '#555' : colors.accent }}
                        onClick={handleToggleView}
                        title={gridView ? "Switch to Canvas View" : "Switch to Grid View"}
                    >
                        <Grid className="h-5 w-5" />
                    </button>
                </div>
            </div>

            {/* Filters */}
            <div className="flex flex-wrap gap-3 mb-6">
                <div className="relative flex-grow max-w-md">
                    <div className="absolute inset-y-0 left-0 pl-3 flex items-center">
                        <Search className="h-5 w-5 text-gray-400" />
                    </div>
                    <input
                        type="text"
                        placeholder="Search concepts..."
                        className="bg-gray-800 text-white pl-10 pr-4 py-2 rounded w-full border border-gray-700"
                        value={searchTerm}
                        onChange={(e) => setSearchTerm(e.target.value)}
                    />
                </div>

                <select
                    value={selectedCategory}
                    onChange={(e) => setSelectedCategory(e.target.value)}
                    className="bg-gray-800 text-white px-3 py-2 rounded border border-gray-700"
                >
                    <option value="All">All Categories</option>
                    {categories.map(category => (
                        <option key={category} value={category}>{category}</option>
                    ))}
                </select>
            </div>

            {gridView ? (
                // Grid View
                <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 lg:grid-cols-4 gap-4">
                    {filteredConcepts.length === 0 ? (
                        <div className="col-span-full py-10 text-center text-gray-400">
                            No concept art found. Upload some or adjust your filters.
                        </div>
                    ) : (
                        filteredConcepts.map(concept => (
                            <div
                                key={concept.id}
                                className="bg-gray-800 rounded overflow-hidden hover-glow transition-all cursor-pointer"
                                onClick={() => handleSelectConcept(concept)}
                            >
                                <div className="aspect-w-4 aspect-h-3 relative">
                                    <img
                                        src={concept.thumbnail || '/placeholder.png'}
                                        alt={concept.name}
                                        className="object-cover w-full h-48"
                                        onError={(e) => {
                                            e.target.src = '/placeholder.png';
                                        }}
                                    />
                                    <div className="absolute top-2 right-2 bg-gray-900 bg-opacity-75 rounded-full px-2 py-1 text-xs text-white">
                                        {concept.category}
                                    </div>
                                </div>
                                <div className="p-3">
                                    <h3 className="text-white font-medium truncate">{concept.name}</h3>
                                    <div className="flex flex-wrap gap-1 mt-2">
                                        {concept.tags.slice(0, 3).map(tag => (
                                            <span
                                                key={tag}
                                                className="px-2 py-1 bg-gray-700 rounded-full text-xs text-gray-300"
                                            >
                                                {tag}
                                            </span>
                                        ))}
                                        {concept.tags.length > 3 && (
                                            <span className="px-2 py-1 bg-gray-700 rounded-full text-xs text-gray-300">
                                                +{concept.tags.length - 3}
                                            </span>
                                        )}
                                    </div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            ) : (
                // Canvas View
                <div
                    ref={boardRef}
                    className="bg-gray-900 rounded-lg overflow-hidden relative h-[600px] cursor-grab"
                    style={{ width: '200%' }} // Make the board wider
                    onMouseDown={handleBoardMouseDown}
                    onMouseMove={handleBoardMouseMove}
                    onMouseUp={handleBoardMouseUp}
                    onMouseLeave={handleBoardMouseUp}
                    onWheel={handleBoardWheel}
                >
                    <div
                        ref={boardWidthRef}
                        className="absolute"
                        style={{
                            transform: `translate(${boardOffset.x}px, <span class="math-inline">\{boardOffset\.y\}px\) scale\(</span>{scale})`,
                            transformOrigin: 'top left',
                            width: '50%', // Match the visual width
                            height: '100%'
                        }}
                    >
                        {filteredConcepts.map(concept => (
                            <div
                                key={concept.id}
                                className="absolute bg-gray-800 rounded shadow-lg overflow-hidden cursor-move hover-glow"
                                style={{
                                    left: `${concept.position.x}px`,
                                    top: `${concept.position.y}px`,
                                    transform: `scale(${concept.scale})`,
                                    zIndex: selectedConcept?.id === concept.id ? 10 : 1,
                                }}
                                onClick={(e) => {
                                    e.stopPropagation();
                                    handleSelectConcept(concept);
                                }}
                                draggable="true"
                                onDragStart={(e) => handleConceptDragStart(e, concept.id)}
                                onDragOver={handleConceptDragOver}
                                onDrop={handleConceptDrop}
                            >
                                <img
                                    src={concept.thumbnail || '/placeholder.png'}
                                    alt={concept.name}
                                    className="w-48 h-32 object-cover"
                                    onError={(e) => {
                                        e.target.src = '/placeholder.png';
                                    }}
                                />
                                <div className="p-2 flex justify-between items-center">
                                    <h3 className="text-white text-sm font-medium truncate w-3/4">{concept.name}</h3>
                                    <button
                                        onClick={(e) => {
                                            e.stopPropagation();
                                            handleDeleteConcept(concept.id);
                                        }}
                                        className="text-gray-400 hover:text-red-500"
                                        title="Delete concept"
                                    >
                                        <Trash2 className="h-4 w-4" />
                                    </button>
                                </div>
                            </div>
                        ))}
                    </div>

                    {/* Zoom controls */}
                    <div className="absolute bottom-4 right-4 flex space-x-2">
                        <button
                            className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
                            onClick={handleZoomIn}
                        >
                            <ZoomIn className="h-5 w-5" />
                        </button>
                        <button
                            className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
                            onClick={handleZoomOut}
                        >
                            <ZoomOut className="h-5 w-5" />
                        </button>
                        <button
                            className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700"
                            onClick={handleResetZoom}
                        >
                            <span className="text-sm">1:1</span>
                        </button>
                    </div>

                    {filteredConcepts.length ===0 && (
                        <div className="absolute inset-0 flex items-center justify-center text-gray-400">
                            No concept art uploaded yet. Click "Upload" to add some!
                        </div>
                    )}
                </div>
            )}

            {/* Concept Detail Modal */}
            {selectedConcept && (
                <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
                    <div className="bg-gray-900 rounded-lg max-w-4xl w-full max-h-[90vh] overflow-hidden flex flex-col">
                        <div className="flex justify-between items-center p-4 border-b border-gray-800">
                            <input
                                type="text"
                                className="bg-transparent border-0 text-lg font-bold text-white focus:ring-0"
                                value={selectedConcept.name}
                                onChange={(e) => handleUpdateConcept({ ...selectedConcept, name: e.target.value })}
                            />
                            <div className="flex space-x-2">
                                <button
                                    className="text-gray-400 hover:text-white"
                                    onClick={handleCloseDetail}
                                >
                                    <X className="h-6 w-6" />
                                </button>
                            </div>
                        </div>

                        <div className="flex-grow overflow-y-auto p-4">
                            <div className="flex flex-col md:flex-row gap-6">
                                <div className="md:w-3/5">
                                    <div className="bg-black rounded overflow-hidden">
                                        <img
                                            src={selectedConcept.fullImage || '/placeholder.png'}
                                            alt={selectedConcept.name}
                                            className="w-full object-contain max-h-[60vh]"
                                            onError={(e) => {
                                                e.target.src = '/placeholder.png';
                                            }}
                                        />
                                    </div>

                                    <div className="flex justify-between mt-4">
                                        {/* Zoom controls for detailed view (optional) */}
                                        {/* <div className="flex space-x-2">
                                            <button className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700">
                                                <ZoomIn className="h-5 w-5" />
                                            </button>
                                            <button className="p-2 rounded bg-gray-800 text-white hover:bg-gray-700">
                                                <ZoomOut className="h-5 w-5" />
                                            </button>
                                        </div> */}

                                        <div>
                                            <button
                                                className="p-2 rounded bg-red-900 text-white hover:bg-red-800"
                                                title="Delete concept"
                                                onClick={() => handleDeleteConcept(selectedConcept.id)}
                                            >
                                                <Trash2 className="h-5 w-5" />
                                            </button>
                                        </div>
                                    </div>
                                </div>

                                <div className="md:w-2/5">
                                    <div className="space-y-4">
                                        <div>
                                            <h4 className="text-sm text-gray-400 mb-1">Category</h4>
                                            <div className="flex items-center">
                                                <select
                                                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                                                    value={selectedConcept.category}
                                                    onChange={(e) => handleUpdateConcept({ ...selectedConcept, category: e.target.value })}
                                                >
                                                    {categories.map(category => (
                                                        <option key={category} value={category}>{category}</option>
                                                    ))}
                                                </select>
                                            </div>
                                        </div>

                                        <div>
                                            <h4 className="text-sm text-gray-400 mb-1">Tags</h4>
                                            <div className="flex flex-wrap gap-2">
                                                {selectedConcept.tags.map(tag => (
                                                    <span
                                                        key={tag}
                                                        className="px-2 py-1 bg-gray-700 rounded-full text-sm text-white"
                                                    >
                                                        {tag}
                                                    </span>
                                                ))}

                                                {/* Add tag functionality (not implemented in this version) */}
                                                {/* <button
                                                    className="px-2 py-1 bg-gray-800 rounded-full border border-dashed border-gray-600 text-sm text-gray-400 flex items-center"
                                                >
                                                    <Plus className="h-3 w-3 mr-1" />
                                                    Add tag
                                                </button> */}
                                            </div>
                                        </div>

                                        <div>
                                            <h4 className="text-sm text-gray-400 mb-1">Created</h4>
                                            <p className="text-white">{selectedConcept.createdAt}</p>
                                        </div>

                                        <div>
                                            <h4 className="text-sm text-gray-400 mb-1">Notes</h4>
                                            <textarea
                                                className="w-full bg-gray-800 border border-gray-700 rounded p-2 text-white h-32"
                                                placeholder="Add notes about this concept..."
                                                value={selectedConcept.notes || ''}
                                                onChange={(e) => handleUpdateConcept({ ...selectedConcept, notes: e.target.value })}
                                            />
                                        </div>

                                        <div>
                                            <h4 className="text-sm text-gray-400 mb-1">Related Concepts</h4>
                                            <div className="grid grid-cols-3 gap-2">
                                                {conceptArt
                                                    .filter(c => c.id !== selectedConcept.id && c.category === selectedConcept.category)
                                                    .slice(0, 3)
                                                    .map(concept => (
                                                        <div
                                                            key={concept.id}
                                                            className="bg-gray-800 rounded overflow-hidden cursor-pointer"
                                                            onClick={() => handleSelectConcept(concept)}
                                                        >
                                                            <img
                                                                src={concept.thumbnail || '/placeholder.png'}
                                                                alt={concept.name}
                                                                className="w-full h-16 object-cover"
                                                            />
                                                            <div className="p-1">
                                                                <p className="text-white text-xs truncate">{concept.name}</p>
                                                            </div>
                                                        </div>
                                                    ))}

                                                {conceptArt.filter(c => c.id !== selectedConcept.id && c.category === selectedConcept.category).length === 0 && (
                                                    <div className="col-span-3 text-center text-gray-500 py-2">
                                                        No related concepts found
                                                    </div>
                                                )}
                                            </div>
                                        </div>
                                    </div>
                                </div>
                            </div>
                        </div>

                        <div className="border-t border-gray-800 p-4 flex justify-end">
                            <button
                                className="px-4 py-2 rounded bg-gray-800 text-white hover:bg-gray-700 mr-2"
                                onClick={handleCloseDetail}
                            >
                                Close
                            </button>
                            <button
                                className="px-4 py-2 rounded text-white hover-scale transition-all"
                                style={{ backgroundColor: colors.accent }}
                                onClick={handleCloseDetail}
                            >
                                Save Changes
                            </button>
                        </div>
                    </div>
                </div>
            )}

            {/* Upload Modal */}
            {showUploadModal && (
                <div className="fixed inset-0 bg-black bg-opacity-75 flex items-center justify-center z-50 p-4">
                    <div className="bg-gray-900 rounded-lg max-w-md w-full overflow-hidden">
                        <div className="flex justify-between items-center p-4 border-b border-gray-800">
                            <h3 className="text-lg font-bold text-white">Upload Concept Art</h3>
                            <button
                                className="text-gray-400 hover:text-white"
                                onClick={() => setShowUploadModal(false)}
                            >
                                <X className="h-6 w-6" />
                            </button>
                        </div>

                        <div className="p-6">
                            <div
                                className="border-2 border-dashed border-gray-700 rounded-lg p-8 text-center cursor-pointer"
                                onClick={() => fileInputRef.current?.click()}
                            >
                                <input
                                    type="file"
                                    ref={fileInputRef}
                                    className="hidden"
                                    accept="image/*"
                                    multiple
                                    onChange={handleFileSelect}
                                />
                                <Upload className="h-12 w-12 mx-auto text-gray-400 mb-4" />
                                <p className="text-white mb-2">Drag & drop or click to upload</p>
                                <p className="text-gray-400 text-sm">PNG, JPG, GIF up to 10MB</p>
                            </div>

                            <div className="mt-4">
                                <label className="block text-gray-400 mb-1 text-sm">Category</label>
                                <select
                                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                                    value={newConceptCategory}
                                    onChange={(e) => setNewConceptCategory(e.target.value)}
                                >
                                    <option value="">Select category</option>
                                    {categories.map(category => (
                                        <option key={category} value={category}>{category}</option>
                                    ))}
                                </select>
                            </div>

                            <div className="mt-4">
                                <label className="block text-gray-400 mb-1 text-sm">Tags (comma separated)</label>
                                <input
                                    type="text"
                                    className="w-full bg-gray-800 border border-gray-700 rounded px-3 py-2 text-white"
                                    placeholder="character, concept, main, ..."
                                    value={newConceptTags}
                                    onChange={(e) => setNewConceptTags(e.target.value)}
                                />
                            </div>
                        </div>

                        <div className="border-t border-gray-800 p-4 flex justify-end">
                            <button
                                className="px-4 py-2 rounded bg-gray-800 text-white hover:bg-gray-700 mr-2"
                                onClick={() => setShowUploadModal(false)}
                            >
                                Cancel
                            </button>
                            <button
                                className="px-4 py-2 rounded text-white hover-scale transition-all"
                                style={{ backgroundColor: colors.accent }}
                                onClick={() => fileInputRef.current?.click()}
                            >
                                Upload
                            </button>
                        </div>
                    </div>
                </div>
            )}
        </div>
    );
};

export default ConceptBoard;
